PRIO=[LE,EP,PP,PEN,ADM,DH,ET,LP,CON,RL,INF,CG]
def classifica(txt,ctx=''):
    t=txt+' '+ctx[-300:]
    if re.search(r'contab',t,re.I): return CG
    if re.search(r'\d+\s?%|conjunto verdade|universo',t,re.I) and re.search(r'quant|total|n[úu]mero|corresponde|conjunto verdade|percentual',t,re.I) and not re.search(r'lei|art\.|c[óo]digo',t,re.I): return RL
    sc={}
    for d,(forte,fraco) in K.items():
        s=3*len(re.findall(forte,t,re.I)) if forte else 0
        if fraco: s+=len(re.findall(fraco,t,re.I))
        sc[d]=s
    best=max(sc.values())
    if best==0: return CG
    for d in PRIO:
        if sc[d]==best: return d
